import { SignaturePad } from '@absoluteui/components/signature-pad';

const host = document.createElement('div');
const preview = document.createElement('img');
preview.alt = 'Exported signature';
document.body.append(host, preview);
const pad = SignaturePad.create(host, { label: 'Signature', description: 'Draw your signature or type your full name.', required: true, name: 'signature' });
host.addEventListener('aui-change', () => {
  preview.src = pad.isEmpty ? '' : pad.toDataURL('svg');
});

